<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Http\Requests\InitializeCheckoutRequest;use App\Http\Requests\QuoteCheckoutRequest;use App\Models\Order;use App\Services\Commerce\CheckoutService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class CheckoutController extends Controller{public function quote(QuoteCheckoutRequest $request,CheckoutService $checkout):JsonResponse{return response()->json(['data'=>$checkout->quote($request->validated('items'))]);}public function initialize(InitializeCheckoutRequest $request,CheckoutService $checkout):JsonResponse{return response()->json(['data'=>$checkout->initialize($request->validated(),auth('sanctum')->id())],201);}public function show(Request $request,string $id,CheckoutService $checkout):JsonResponse{$order=Order::query()->where('public_id',$id)->firstOrFail();$checkout->authorizeOrderAccess($order,auth('sanctum')->id(),$request->header('X-Checkout-Token'));return response()->json(['data'=>$checkout->publicOrderPayload($order)]);}public function verify(Request $request,string $reference,CheckoutService $checkout):JsonResponse{$order=$checkout->verify($reference,auth('sanctum')->id(),$request->header('X-Checkout-Token'));return response()->json(['data'=>$checkout->publicOrderPayload($order)]);}}